export type CategoryId =
  | 'web'
  | 'messaging'
  | 'media'
  | 'imaging'
  | 'documents'
  | 'security'
  | 'cloud'
  | 'utilities'
  | 'developer'
  | 'runtimes'
  | 'gaming'

/**
 * The ways a single app can be installed on the target PC.
 *
 * A browser cannot know which package managers exist on the user's machine, so
 * every app carries more than one way in and the generated PowerShell script
 * probes for them at runtime, in order, falling through on failure.
 */
export interface AppSources {
  /** Windows Package Manager ID. Ships with Windows 10 1809+ and Windows 11. */
  winget: string
  /** Chocolatey (community) package ID. */
  choco: string
  /** Scoop manifest name. */
  scoop: string
  /** Direct vendor installer URL, used when no package manager is available. */
  directUrl?: string
  /** File name the direct download is saved as, then executed. */
  directExe?: string
  /** Silent switches passed to the direct installer. */
  directArgs?: string
}

export interface AppSoftware {
  id: string
  name: string
  vendor: string
  category: CategoryId
  description: string
  website: string
  color: string
  /** lucide-react icon name, kept only as an offline fallback. */
  icon: string
  /** Bundled real brand mark, e.g. '/icons/googlechrome.svg'. Empty when none was available. */
  logo: string
  /** Remote favicon/logo for the vendor site, used when the bundled mark is missing or fails. */
  logoFallback: string
  minRamGB: number
  recommendedRamGB: number
  minCores: number
  minDiskMB: number
  wingetId: string
  sources: AppSources
  notes?: string
  popular?: boolean
}

export interface Category {
  id: CategoryId
  name: string
  blurb: string
  color: string
  icon: string
}

