export function getApp(id: string): AppSoftware | undefined {
  return APPS.find((a) => a.id === id)
}

export function appsByCategory(category: CategoryId): AppSoftware[] {
  return APPS.filter((a) => a.category === category)
}

export function categoryCount(category: CategoryId): number {
  let n = 0
  for (const a of APPS) if (a.category === category) n++
  return n
}
